select:
select a.id AS id, a.cause_analysis AS causeAnalysis, a.corrective_action AS correctiveAction, a.preventive_measure AS preventiveMeasure, DATE_FORMAT(a.created_time, '%Y-%m-%d %H:%i:%s') AS createdTime, DATE_FORMAT(a.update_time, '%Y-%m-%d %H:%i:%s') AS updateTime, cs.`name` AS createdStaffName, us.`name` AS updateStaffName, a.submit_status AS submitStatus, a.expected_completion_date as expectedCompletionDate from jml_case_qa_opinion a left join jml_staff cs on a.created_staff_id = cs.id left join jml_staff us ON a.update_staff_id = us.id
and a.case_id = #{caseId}
order by a.created_time desc

select a.id AS id, a.cause_analysis AS causeAnalysis, a.corrective_action AS correctiveAction, a.preventive_measure AS preventiveMeasure, DATE_FORMAT(a.created_time, '%Y-%m-%d %H:%i:%s') AS createdTime, DATE_FORMAT(a.update_time, '%Y-%m-%d %H:%i:%s') AS updateTime, cs.`name` AS createdStaffName, us.`name` AS updateStaffName, a.submit_status AS submitStatus, DATE_FORMAT(a.expected_completion_date, '%Y-%m-%d') as expectedCompletionDate from jml_case_qa_opinion a left join jml_staff cs on a.created_staff_id = cs.id left join jml_staff us ON a.update_staff_id = us.id
a.id=#{id}
a.case_id = #{caseId}
